// Raven `qboolean` is `c_int`; keep the source spelling at assignment sites.
// Source: `oracle/oracle/codemp/game/q_shared.h`
const qtrue: qboolean = 1;
const qfalse: qboolean = 0;

// Raven angle-vector indices (`q_shared.h`): PITCH=0, YAW=1, ROLL=2.
const PITCH: usize = 0;
const YAW: usize = 1;
const ROLL: usize = 2;

/// Raven `ObjectDie`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:22-31`
pub fn ObjectDie(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    inflictor: *mut gentity_t,
    attacker: *mut gentity_t,
    damage: c_int,
    meansOfDeath: c_int,
) {
    unsafe {
        if !(*self_).target.is_null() {
            G_UseTargets(ctx, self_, attacker);
        }

        // remove my script_targetname
        G_FreeEntity(ctx, self_);
    }
}

