/// Raven `G_GetHitLocation`.
///
/// `ppoint` is read-only (the impact point is copied *from* it), so it stays
/// by-value per the fork-9 rule.
/// Source: `oracle/oracle/codemp/game/g_combat.c:46-266`
pub fn G_GetHitLocation(ctx: GameContext<'_>, target: *mut gentity_t, ppoint: vec3_t) -> c_int {
    unsafe {
        let mut point: vec3_t = [0.0; 3];
        let mut point_dir: vec3_t = [0.0; 3];
        let mut forward: vec3_t = [0.0; 3];
        let mut right: vec3_t = [0.0; 3];
        let mut up: vec3_t = [0.0; 3];
        let mut tangles: vec3_t = [0.0; 3];
        let mut tcenter: vec3_t = [0.0; 3];

        // Get target forward, right and up.
        if !(*target).client.is_null() {
            // Ignore player's pitch and roll.
            tangles = [0.0, (*target).r.currentAngles[YAW], 0.0];
        }

        AngleVectors(tangles, Some(&mut forward), Some(&mut right), Some(&mut up));

        // Get center of target.
        for i in 0..3 {
            tcenter[i] = ((*target).r.absmin[i] + (*target).r.absmax[i]) * 0.5;
        }

        // Get radius width of target (kept for parity; unused below like Raven).
        let _tradius = ((*target).r.maxs[0].abs()
            + (*target).r.maxs[1].abs()
            + (*target).r.mins[0].abs()
            + (*target).r.mins[1].abs())
            / 4.0;

        // Get impact point.
        if ppoint[0] != 0.0 || ppoint[1] != 0.0 || ppoint[2] != 0.0 {
            point = ppoint;
        } else {
            return HL_NONE;
        }

        for i in 0..3 {
            point_dir[i] = point[i] - tcenter[i];
        }
        VectorNormalize(&mut point_dir);

        let dot = |a: &vec3_t, b: &vec3_t| a[0] * b[0] + a[1] * b[1] + a[2] * b[2];

        // Get bottom to top (vertical) position index.
        let udot = dot(&up, &point_dir);
        let vertical = if udot > 0.800 {
            4
        } else if udot > 0.400 {
            3
        } else if udot > -0.333 {
            2
        } else if udot > -0.666 {
            1
        } else {
            0
        };

        // Get back to front (forward) position index.
        let fdot = dot(&forward, &point_dir);
        let forward_idx = if fdot > 0.666 {
            4
        } else if fdot > 0.333 {
            3
        } else if fdot > -0.333 {
            2
        } else if fdot > -0.666 {
            1
        } else {
            0
        };

        // Get left to right (lateral) position index.
        let rdot = dot(&right, &point_dir);
        let lateral = if rdot > 0.666 {
            4
        } else if rdot > 0.333 {
            3
        } else if rdot > -0.333 {
            2
        } else if rdot > -0.666 {
            1
        } else {
            0
        };

        let hit_loc = vertical * 25 + forward_idx * 5 + lateral;

        if hit_loc <= 10 {
            // Feet.
            if rdot > 0.0 { HL_FOOT_RT } else { HL_FOOT_LT }
        } else if hit_loc <= 50 {
            // Legs.
            if rdot > 0.0 { HL_LEG_RT } else { HL_LEG_LT }
        } else if hit_loc == 56
            || hit_loc == 60
            || hit_loc == 61
            || hit_loc == 65
            || hit_loc == 66
            || hit_loc == 70
        {
            // Hands.
            if rdot > 0.0 { HL_HAND_RT } else { HL_HAND_LT }
        } else if hit_loc == 83
            || hit_loc == 87
            || hit_loc == 88
            || hit_loc == 92
            || hit_loc == 93
            || hit_loc == 97
        {
            // Arms.
            if rdot > 0.0 { HL_ARM_RT } else { HL_ARM_LT }
        } else if (107..=109).contains(&hit_loc)
            || (112..=114).contains(&hit_loc)
            || (117..=119).contains(&hit_loc)
        {
            // Head.
            HL_HEAD
        } else if udot < 0.3 {
            HL_WAIST
        } else if fdot < 0.0 {
            if rdot > 0.4 {
                HL_BACK_RT
            } else if rdot < -0.4 {
                HL_BACK_LT
            } else if fdot < 0.0 {
                HL_BACK
            } else {
                HL_NONE
            }
        } else if rdot > 0.3 {
            HL_CHEST_RT
        } else if rdot < -0.3 {
            HL_CHEST_LT
        } else if fdot < 0.0 {
            HL_CHEST
        } else {
            HL_NONE
        }
    }
}

/// Raven `ExplodeDeath`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:369-409`
pub fn ExplodeDeath(ctx: GameContext<'_>, self_: *mut gentity_t) {
    unsafe {
        let mut forward: vec3_t = [0.0; 3];

        (*self_).takedamage = qfalse; // stop chain reaction runaway loops

        (*self_).s.loopSound = 0;
        (*self_).s.loopIsSoundset = qfalse;

        (*self_).s.pos.trBase = (*self_).r.currentOrigin;

        AngleVectors((*self_).s.angles, Some(&mut forward), None, None);

        if (*self_).splashDamage > 0 && (*self_).splashRadius > 0 {
            let mut attacker = self_;
            if !(*self_).parent.is_none() {
                attacker = (*self_).parent;
            }
            G_RadiusDamage(
                ctx,
                (*self_).r.currentOrigin,
                attacker,
                (*self_).splashDamage as f32,
                (*self_).splashRadius as f32,
                attacker,
                core::ptr::null_mut(),
                meansOfDeath_t::MOD_UNKNOWN as c_int,
            );
        }

        ObjectDie(ctx, self_, self_, self_, 20, 0);
    }
}

