/// Raven `G_InKnockDown`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:853-880`
pub fn G_InKnockDown(ps: *mut playerState_t) -> qboolean {
    use animNumber_t::*;
    unsafe {
        let legs = (*ps).legsAnim;
        let knockdowns = [
            BOTH_KNOCKDOWN1,
            BOTH_KNOCKDOWN2,
            BOTH_KNOCKDOWN3,
            BOTH_KNOCKDOWN4,
            BOTH_KNOCKDOWN5,
            BOTH_GETUP1,
            BOTH_GETUP2,
            BOTH_GETUP3,
            BOTH_GETUP4,
            BOTH_GETUP5,
            BOTH_FORCE_GETUP_F1,
            BOTH_FORCE_GETUP_F2,
            BOTH_FORCE_GETUP_B1,
            BOTH_FORCE_GETUP_B2,
            BOTH_FORCE_GETUP_B3,
            BOTH_FORCE_GETUP_B4,
            BOTH_FORCE_GETUP_B5,
        ];
        if knockdowns.iter().any(|&a| a as c_int == legs) {
            qtrue
        } else {
            qfalse
        }
    }
}

