/// Raven `G_PickDeathAnim`.
///
/// Raven: FIXME: play dead flop anims on body if in an appropriate _DEAD anim
/// when this func is called.
/// `point` is read-only (forwarded to `G_GetHitLocation`), so it stays
/// by-value.
/// Source: `oracle/oracle/codemp/game/g_combat.c:1374-1742`
pub fn G_PickDeathAnim(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    point: vec3_t,
    damage: c_int,
    r#mod: c_int,
    mut hitLoc: c_int,
) -> c_int {
    use animNumber_t::*;
    unsafe {
        let mut deathAnim: c_int = -1;
        let max_health: c_int;
        let mut objVelocity: vec3_t = [0.0; 3];

        if self_.is_null() || (*self_).client.is_null() {
            if self_.is_null() || (*self_).s.eType != entityType_t::ET_NPC as c_int {
                // g2animent
                return 0;
            }
        }

        if !(*self_).client.is_null() {
            let cl = (*self_).client as *mut gclient_t;
            max_health = (*cl).ps.stats[statIndex_t::STAT_MAX_HEALTH as usize];

            if (*cl).inSpaceIndex != 0
                && (*cl).inSpaceIndex != mp_qshared::shared::limits::ENTITYNUM_NONE
            {
                return BOTH_CHOKE3 as c_int;
            }
        } else {
            max_health = 60;
        }

        if !(*self_).client.is_null() {
            objVelocity = (*((*self_).client as *mut gclient_t)).ps.velocity;
        } else {
            objVelocity = (*self_).s.pos.trDelta;
        }

        if hitLoc == HL_NONE {
            hitLoc = G_GetHitLocation(ctx, self_, point); // self->hitLoc
        }

        let legAnim = if !(*self_).client.is_null() {
            (*((*self_).client as *mut gclient_t)).ps.legsAnim
        } else {
            (*self_).s.legsAnim
        };

        if (*ctx.world).globals.gGAvoidDismember != 0 {
            return BOTH_RIGHTHANDCHOPPEDOFF as c_int;
        }

        // dead flops — every listed anim resolves to `deathAnim = -2` (the
        // conditional DEADFLOP re-selects are commented out in Raven).
        let dead_flops = [
            BOTH_DEATH1,
            BOTH_DEAD1,
            BOTH_DEATH2,
            BOTH_DEAD2,
            BOTH_DEATH8,
            BOTH_DEAD8,
            BOTH_DEATH13,
            BOTH_DEAD13,
            BOTH_DEATH14,
            BOTH_DEAD14,
            BOTH_DEATH16,
            BOTH_DEAD16,
            BOTH_DEADBACKWARD1,
            BOTH_DEADBACKWARD2,
            BOTH_DEATH10,
            BOTH_DEAD10,
            BOTH_DEATH15,
            BOTH_DEAD15,
            BOTH_DEADFORWARD1,
            BOTH_DEADFORWARD2,
            BOTH_DEADFLOP1,
            BOTH_DEAD3,
            BOTH_DEAD4,
            BOTH_DEAD5,
            BOTH_DEAD6,
            BOTH_DEAD7,
            BOTH_DEAD9,
            BOTH_DEAD11,
            BOTH_DEAD12,
            BOTH_DEAD17,
            BOTH_DEAD18,
            BOTH_DEAD19,
            BOTH_LYINGDEAD1,
            BOTH_STUMBLEDEAD1,
            BOTH_FALLDEAD1LAND,
            BOTH_DEATH3,
            BOTH_DEATH4,
            BOTH_DEATH5,
            BOTH_DEATH6,
            BOTH_DEATH7,
            BOTH_DEATH9,
            BOTH_DEATH11,
            BOTH_DEATH12,
            BOTH_DEATH17,
            BOTH_DEATH18,
            BOTH_DEATH19,
            BOTH_DEATHFORWARD1,
            BOTH_DEATHFORWARD2,
            BOTH_DEATHBACKWARD1,
            BOTH_DEATHBACKWARD2,
            BOTH_DEATH1IDLE,
            BOTH_LYINGDEATH1,
            BOTH_STUMBLEDEATH1,
            BOTH_FALLDEATH1,
            BOTH_FALLDEATH1INAIR,
            BOTH_FALLDEATH1LAND,
        ];
        if dead_flops.iter().any(|&a| a as c_int == legAnim) {
            deathAnim = -2;
        }

        if deathAnim == -1 {
            if !(*self_).client.is_null() {
                deathAnim = G_CheckSpecialDeathAnim(ctx, self_, point, damage, r#mod, hitLoc);
            }

            if deathAnim == -1 {
                let dmg = damage as f32;
                let mh = max_health as f32;
                // death anims
                if hitLoc == HL_FOOT_RT || hitLoc == HL_FOOT_LT {
                    if r#mod == meansOfDeath_t::MOD_SABER as c_int && Q_irand(0, 2) == 0 {
                        return BOTH_DEATH10 as c_int; // chest: back flip
                    } else if Q_irand(0, 2) == 0 {
                        deathAnim = BOTH_DEATH4 as c_int;
                    } else if Q_irand(0, 1) == 0 {
                        deathAnim = BOTH_DEATH5 as c_int;
                    } else {
                        deathAnim = BOTH_DEATH15 as c_int;
                    }
                } else if hitLoc == HL_LEG_RT || hitLoc == HL_LEG_LT {
                    if Q_irand(0, 2) == 0 {
                        deathAnim = BOTH_DEATH4 as c_int;
                    } else if Q_irand(0, 1) == 0 {
                        deathAnim = BOTH_DEATH5 as c_int;
                    } else {
                        deathAnim = BOTH_DEATH15 as c_int;
                    }
                } else if hitLoc == HL_BACK {
                    if VectorLengthSquared(objVelocity) == 0.0 {
                        deathAnim = BOTH_DEATH17 as c_int; // head/back: croak
                    } else if Q_irand(0, 2) == 0 {
                        deathAnim = BOTH_DEATH4 as c_int;
                    } else if Q_irand(0, 1) == 0 {
                        deathAnim = BOTH_DEATH5 as c_int;
                    } else {
                        deathAnim = BOTH_DEATH15 as c_int;
                    }
                } else if hitLoc == HL_CHEST_RT
                    || hitLoc == HL_ARM_RT
                    || hitLoc == HL_HAND_RT
                    || hitLoc == HL_BACK_RT
                {
                    if dmg <= mh * 0.25 {
                        deathAnim = BOTH_DEATH9 as c_int;
                    } else if dmg <= mh * 0.5 {
                        deathAnim = BOTH_DEATH3 as c_int;
                    } else if dmg <= mh * 0.75 {
                        deathAnim = BOTH_DEATH6 as c_int;
                    } else if Q_irand(0, 1) != 0 {
                        deathAnim = BOTH_DEATH8 as c_int; // TEMP HACK: play spinny deaths less often
                    } else {
                        deathAnim = match Q_irand(0, 2) {
                            1 => BOTH_DEATH3 as c_int,
                            2 => BOTH_DEATH6 as c_int,
                            _ => BOTH_DEATH9 as c_int,
                        };
                    }
                } else if hitLoc == HL_CHEST_LT
                    || hitLoc == HL_ARM_LT
                    || hitLoc == HL_HAND_LT
                    || hitLoc == HL_BACK_LT
                {
                    if dmg <= mh * 0.25 {
                        deathAnim = BOTH_DEATH11 as c_int;
                    } else if dmg <= mh * 0.5 {
                        deathAnim = BOTH_DEATH7 as c_int;
                    } else if dmg <= mh * 0.75 {
                        deathAnim = BOTH_DEATH12 as c_int;
                    } else if Q_irand(0, 1) != 0 {
                        deathAnim = BOTH_DEATH14 as c_int;
                    } else {
                        deathAnim = match Q_irand(0, 2) {
                            1 => BOTH_DEATH7 as c_int,
                            2 => BOTH_DEATH12 as c_int,
                            _ => BOTH_DEATH11 as c_int,
                        };
                    }
                } else if hitLoc == HL_CHEST || hitLoc == HL_WAIST {
                    if dmg <= mh * 0.25 || VectorLengthSquared(objVelocity) == 0.0 {
                        if Q_irand(0, 1) == 0 {
                            deathAnim = BOTH_DEATH18 as c_int; // gut: fall right
                        } else {
                            deathAnim = BOTH_DEATH19 as c_int; // gut: fall left
                        }
                    } else if dmg <= mh * 0.5 {
                        deathAnim = BOTH_DEATH2 as c_int;
                    } else if dmg <= mh * 0.75 {
                        if Q_irand(0, 1) == 0 {
                            deathAnim = BOTH_DEATH1 as c_int;
                        } else {
                            deathAnim = BOTH_DEATH16 as c_int;
                        }
                    } else {
                        deathAnim = BOTH_DEATH10 as c_int; // chest: back flip
                    }
                } else if hitLoc == HL_HEAD {
                    if dmg <= mh * 0.5 {
                        deathAnim = BOTH_DEATH17 as c_int; // head/back: croak
                    } else {
                        deathAnim = BOTH_DEATH13 as c_int; // head: stumble, fall back
                    }
                }
            }
        }

        // Validate.....
        if deathAnim == -1 || BG_HasAnimation((*self_).localAnimIndex, deathAnim) == qfalse {
            // I guess we'll take what we can get.....
            deathAnim = BG_PickAnim(
                (*self_).localAnimIndex,
                BOTH_DEATH1 as c_int,
                BOTH_DEATH25 as c_int,
            );
        }

        deathAnim
    }
}

/// Raven `G_GetJediMaster`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:1744-1762`
pub fn G_GetJediMaster(ctx: GameContext<'_>) -> *mut gentity_t {
    unsafe {
        for i in 0..MAX_CLIENTS as usize {
            let ent = &mut (*ctx.world).entities[i] as *mut gentity_t;
            let client = (*ent).client as *mut gclient_t;
            if (*ent).inuse != qfalse
                && !client.is_null()
                && (*client).ps.isJediMaster != qfalse
            {
                return ent;
            }
        }
        core::ptr::null_mut()
    }
}

