/// Raven `G_ThereIsAMaster`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:4432-4450`
pub fn G_ThereIsAMaster(ctx: GameContext<'_>) -> qboolean {
    unsafe {
        for i in 0..MAX_CLIENTS as usize {
            let ent = &mut (*ctx.world).entities[i] as *mut gentity_t;
            let client = (*ent).client as *mut gclient_t;
            if !client.is_null() && (*client).ps.isJediMaster != qfalse {
                return qtrue;
            }
        }
        qfalse
    }
}

/// Raven `G_Knockdown`.
///
/// Source: `oracle/oracle/codemp/game/g_combat.c:4452-4461`
pub fn G_Knockdown(ctx: GameContext<'_>, victim: *mut gentity_t) {
    unsafe {
        if victim.is_null() {
            return;
        }
        let client = (*victim).client as *mut gclient_t;
        if !client.is_null()
            && BG_KnockDownable(&mut (*client).ps as *mut playerState_t) != qfalse
        {
            (*client).ps.forceHandExtend = HANDEXTEND_KNOCKDOWN as c_int;
            (*client).ps.forceDodgeAnim = 0;
            (*client).ps.forceHandExtendTime = (*ctx.world).level.time + 1100;
            (*client).ps.quickerGetup = qfalse;
        }
    }
}

