/// Raven `CanDamage`.
///
/// `origin` is read-only (a trace start point), so it stays by-value.
/// Source: `oracle/oracle/codemp/game/g_combat.c:5768-5815`
pub fn CanDamage(ctx: GameContext<'_>, targ: *mut gentity_t, origin: vec3_t) -> qboolean {
    unsafe {
        let mut tr: trace_t = core::mem::zeroed();
        let mut midpoint: vec3_t = [0.0; 3];
        // Raven `vec3_origin` (zero vector) — passed as the trace bbox.
        let zero: vec3_t = [0.0; 3];

        // use the midpoint of the bounds instead of the origin, because
        // bmodels may have their origin at 0,0,0
        for i in 0..3 {
            midpoint[i] = ((*targ).r.absmin[i] + (*targ).r.absmax[i]) * 0.5;
        }

        // Inlined `trap_Trace(&tr, origin, vec3_origin, vec3_origin, dest,
        // ENTITYNUM_NONE, MASK_SOLID)` — one per candidate destination.
        macro_rules! trace_to {
            ($dest:expr) => {
                trap::Trace(
                    ctx.engine,
                    GTraceArgs::new(
                        &mut tr as *mut trace_t,
                        &origin as *const vec3_t,
                        &zero as *const vec3_t,
                        &zero as *const vec3_t,
                        &$dest as *const vec3_t,
                        ENTITYNUM_NONE,
                        MASK_SOLID,
                    ),
                )
            };
        }

        let mut dest = midpoint;
        trace_to!(dest);
        if tr.fraction == 1.0 || tr.entityNum as c_int == (*targ).s.number {
            return qtrue;
        }

        // this should probably check in the plane of projection, rather than in
        // world coordinate, and also include Z
        dest = midpoint;
        dest[0] += 15.0;
        dest[1] += 15.0;
        trace_to!(dest);
        if tr.fraction == 1.0 {
            return qtrue;
        }

        dest = midpoint;
        dest[0] += 15.0;
        dest[1] -= 15.0;
        trace_to!(dest);
        if tr.fraction == 1.0 {
            return qtrue;
        }

        dest = midpoint;
        dest[0] -= 15.0;
        dest[1] += 15.0;
        trace_to!(dest);
        if tr.fraction == 1.0 {
            return qtrue;
        }

        dest = midpoint;
        dest[0] -= 15.0;
        dest[1] -= 15.0;
        trace_to!(dest);
        if tr.fraction == 1.0 {
            return qtrue;
        }

        qfalse
    }
}

